                "type": "string"
              },
              "uncertainty": {
                "type": "string"
              }
            },
            "required": [
              "statement",
              "type",
              "sourceUnitIds",
              "derivation",
              "uncertainty"
            ]
          }
        }
      },
      "required": [
        "statements"
      ]
    }
  },
  {
    "type": "function",
    "name": "submit_result",
    "description": "GENAU EINMAL am Ende: reicht dein Endergebnis ein. Validierung ist HART (Fehlerliste zurueck = nachbessern und erneut einreichen). Erst eine GUELTIGE Einreichung beendet die Aufgabe.",
    "parameters": {
      "type": "object",
      "properties": {
        "statements": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "statement": {
