      "sourceUnitIds": [
        "AU-0077"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Wenn im About-Me-Bildschirm etwas Neues hochgeladen wird, sollen verbundene Nutzer der Einrichtung eine Popup-Nachricht erhalten.",
      "type": "requirement",
      "sourceUnitIds": [
        "AU-0078"
      ],
