      "sourceUnitIds": [
        "AU-0080"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Bewohner sollen über ihren Account den About-Me-Bereich ihres eigenen Profils nutzen können.",
