      "sourceUnitIds": [
        "AU-0079",
        "AU-0082"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Die Funktionen des Bewohner-Accounts sollen beschränkt werden, um Fehlbedienungen zu minimieren.",
