      "statement": "Für die Entwicklung wird Flutter mit Dart als plattformübergreifender Technologie-Stack verwendet.",
      "type": "decision",
      "sourceUnitIds": [
        "AU-0092",
        "AU-0093",
        "AU-0095"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Die zu verwendenden Versionsstände von Flutter und Dart sollen teamweit vereinheitlicht werden.",
      "type": "requirement",
      "sourceUnitIds": [
        "AU-0095",
        "AU-0102"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Es wurden Flutter Version 3.13.9 und Dart Version 3.1.5 genannt.",
      "type": "architecture",
      "sourceUnitIds": [
        "AU-0102"
      ],
      "derivation": "explicit",
      "uncertainty": "uncertain"
    },
    {
      "statement": "Als Datenbank wird Firebase Firestore empfohlen und vorerst beibehalten.",
