      "sourceUnitIds": [
        "AU-0105",
        "AU-0107"
      ],
      "derivation": "explicit",
      "uncertainty": "uncertain"
    },
    {
      "statement": "Als möglicher Ansatz sollen Daten beim Seitenaufruf aus Firebase geladen und lokal gespeichert werden, damit sie nicht jedes Mal erneut geladen werden müssen.",
