      "sourceUnitIds": [
        "AU-0106"
      ],
      "derivation": "explicit",
      "uncertainty": "uncertain"
    },
    {
      "statement": "Für die lokale Speicherung wurde eine NoSQLite-Datenbank vorgeschlagen.",
      "type": "architecture",
      "sourceUnitIds": [
        "AU-0106",
        "AU-0107"
      ],
      "derivation": "explicit",
      "uncertainty": "uncertain"
    },
    {
      "statement": "Für Entwicklung und Tests soll zunächst Android 11 verwendet werden.",
      "type": "decision",
      "sourceUnitIds": [
        "AU-0111"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Das Team soll zunächst die Entwicklungsumgebung und Abhängigkeiten installieren und ihre Funktionsfähigkeit prüfen.",
